-- ─── 2. the body level ───────────────────────────────────────────────
insert into public.app_config (key, value) values ('clean_body_min_severity', '2') on conflict (key) do nothing;

create or replace function public.clean_body_min()
returns smallint
language sql stable security definer set search_path = public
as $$
  select coalesce((select nullif(btrim(value), '')::smallint from public.app_config where key = 'clean_body_min_severity'), 2)::smallint
$$;

-- ─── 3. folding ──────────────────────────────────────────────────────
create or replace function public.clean_join_short(p text)
returns text
language plpgsql immutable
as $$
declare
  v text := p;
  prev text;
begin
  for i in 1..4 loop
    prev := v;
    v := regexp_replace(v, '(?<![a-z])([a-z]{1,2})[\s._*-]+([a-z]{3,})(?![a-z])', '\1\2', 'g');
    v := regexp_replace(v, '(?<![a-z])([a-z]{3,})[\s._*-]+([a-z]{1,2})(?![a-z])', '\1\2', 'g');
    v := regexp_replace(v, '(?<![a-z])([a-z])[\s._*-]+([a-z]{1,2})(?![a-z])', '\1\2', 'g');
    exit when v = prev;
  end loop;
  return v;
end;
$$;

create or replace function public.clean_join_tiny(p text)
returns text
language plpgsql immutable
as $$
declare
  v text := p;
  prev text;
begin
  for i in 1..4 loop
    prev := v;
    v := regexp_replace(v, '(?<![a-z])([a-z]{1,2})[\s._*-]+([a-z]{1,2})(?![a-z])', '\1\2', 'g');
    exit when v = prev;
  end loop;
  return v;
end;
$$;

/* One alternation per 200 terms (a regex that big compiles once per
   connection and stays cached), longest terms first. */
create or replace function public.blocked_patterns(p_min smallint)
returns text[]
language sql stable security definer set search_path = public
as $$
  with t as (
    select replace(term, ' ', '[\s._*-]*') as alt,
           row_number() over (order by length(term) desc, term) as rn
    from public.blocked_terms
    where severity >= p_min
  ), g as (
    select (rn - 1) / 200 as grp,
           '(?<![a-z])(' || string_agg(alt, '|' order by rn) || ')(?![a-z])' as pat
    from t
    group by (rn - 1) / 200
  )
  select coalesce(array_agg(pat order by grp), '{}'::text[]) from g
$$;

/* The matched text back to the term as listed ("porch_monkey" → "porch monkey"). */
create or replace function public.blocked_canonical(p_match text)
returns text
language sql stable security definer set search_path = public
as $$
  select coalesce(
    (select term from public.blocked_terms
      where p_match ~ ('^' || replace(term, ' ', '[\s._*-]*') || '$')
      order by length(term) desc, term
      limit 1),
    p_match)
$$;

