  for r in
    select distinct m[1] as run
      from regexp_matches(v, '(?<![a-z])([a-z](?:[\s._*-]+[a-z](?![a-z]))+)', 'g') as m
  loop
    v_run := regexp_replace(r.run, '[\s._*-]+', '', 'g');
    v := replace(v, r.run, v_run);
    v_split := replace(v_split, r.run, case when length(v_run) >= 3 then left(v_run, 1) || ' ' || substr(v_run, 2) else v_run end);
  end loop;
  v_join := public.clean_join_short(v);
  v_tiny := public.clean_join_short(public.clean_join_tiny(v));
  variants := array[
    v,
    v_join,
    regexp_replace(v, '([a-z])\1{2,}', '\1', 'g'),
    regexp_replace(v, '([a-z])\1+', '\1', 'g'),
    regexp_replace(v_join, '([a-z])\1+', '\1', 'g'),
    v_split,
    public.clean_join_short(v_split),
    v_tiny,
    regexp_replace(v_tiny, '([a-z])\1+', '\1', 'g')
  ];
  mins := array[p_min, p_min, p_min, p_min, p_min, p_min, p_min, greatest(p_min, 2::smallint), greatest(p_min, 2::smallint)];
  pats1 := public.blocked_patterns(p_min);
  pats2 := public.blocked_patterns(greatest(p_min, 2::smallint));
  for i in 1..array_length(variants, 1) loop
    foreach pat in array (case when mins[i] = p_min then pats1 else pats2 end) loop
      v_m := regexp_match(variants[i], pat);
      if v_m is not null then
        return public.blocked_canonical(v_m[1]);
      end if;
    end loop;
  end loop;
  if p_min <= 1 then
    if v_raw ~ '(?<![0-9a-z])1488(?![0-9a-z])' then return '1488'; end if;
    if v_raw ~ '(?<![0-9a-z])14[ /-]88(?![0-9a-z])' then return substring(v_raw from '14[ /-]88'); end if;
    if position('🖕' in v_raw) > 0 then return '🖕'; end if;
  end if;
  return null;
end;
$$;

/* Kept for update_profile: profile text is a name surface. */
create or replace function public.text_has_blocked_term(p_text text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select public.find_blocked_term(p_text, 1::smallint) is not null
$$;

revoke all on function public.clean_body_min() from public, anon;
revoke all on function public.blocked_patterns(smallint) from public, anon;
revoke all on function public.blocked_canonical(text) from public, anon;
revoke all on function public.find_blocked_term(text, smallint) from public, anon;
revoke all on function public.text_has_blocked_term(text) from public, anon;
grant execute on function public.find_blocked_term(text, smallint) to authenticated;
grant execute on function public.text_has_blocked_term(text) to authenticated;

-- ─── 4. the gate ─────────────────────────────────────────────────────
create or replace function public.assert_clean(p_field text, p_text text, p_min smallint)
returns void
language plpgsql stable security definer set search_path = public
as $$
declare
  v_term text;
  v_sev smallint;
begin
  if p_text is null or p_text = '' then
    return;
  end if;
  v_term := public.find_blocked_term(p_text, p_min);
  if v_term is null then
    return;
  end if;
  select severity into v_sev from public.blocked_terms where term = v_term;
  if coalesce(v_sev, 1) >= 3 then
    raise exception 'That includes a word we don''t allow.' using errcode = '22023', hint = 'blocked_term', detail = p_field;
  end if;
  raise exception 'That includes a word we don''t allow ("%").', v_term using errcode = '22023', hint = 'blocked_term', detail = p_field;
end;
$$;

create or replace function public.clean_text_guard()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_body smallint;
  v_stance text;
begin
  if coalesce(current_setting('agora.skip_clean', true), '') = 'on' then
    return new;
  end if;
  v_body := public.clean_body_min();
  if tg_table_name = 'debate_rooms' then
    if tg_op = 'INSERT' or new.motion is distinct from old.motion then
      if char_length(coalesce(new.motion, '')) > 300 then
        raise exception 'Room titles are 300 characters at most.' using errcode = '22023', hint = 'too_long', detail = 'motion';
      end if;
      perform public.assert_clean('motion', new.motion, 1::smallint);
    end if;
    if new.framing is not null and (tg_op = 'INSERT' or new.framing is distinct from old.framing) then
      perform public.assert_clean('about', new.framing->>'about', v_body);
      for v_stance in select value->>'text' from jsonb_each(coalesce(new.framing->'stances', '{}'::jsonb)) loop
        perform public.assert_clean('stance', v_stance, v_body);
      end loop;
    end if;
  elsif tg_table_name = 'communities' then
    if tg_op = 'INSERT' or new.name is distinct from old.name then perform public.assert_clean('name', new.name, 1::smallint); end if;
    if tg_op = 'INSERT' or new.description is distinct from old.description then perform public.assert_clean('description', new.description, v_body); end if;
    if tg_op = 'INSERT' or new.rules is distinct from old.rules then perform public.assert_clean('rules', new.rules, v_body); end if;
    if tg_op = 'INSERT' or new.application_prompt is distinct from old.application_prompt then perform public.assert_clean('application_prompt', new.application_prompt, v_body); end if;
    if tg_op = 'INSERT' or new.bookmarks is distinct from old.bookmarks then perform public.assert_clean('bookmarks', new.bookmarks::text, v_body); end if;
  elsif tg_table_name = 'community_posts' then
    if tg_op = 'INSERT' or new.title is distinct from old.title then perform public.assert_clean('title', new.title, 1::smallint); end if;
    if tg_op = 'INSERT' or new.body is distinct from old.body then perform public.assert_clean('body', new.body, v_body); end if;
  elsif tg_table_name in ('community_comments', 'clip_comments') then
    if tg_op = 'INSERT' or new.body is distinct from old.body then perform public.assert_clean('body', new.body, v_body); end if;
  elsif tg_table_name = 'room_messages' then
    if tg_op = 'INSERT' or new.content is distinct from old.content then perform public.assert_clean('content', new.content, v_body); end if;
  elsif tg_table_name = 'users' then
    if new.username is distinct from old.username then perform public.assert_clean('username', new.username, 1::smallint); end if;
    if new.display_name is distinct from old.display_name then perform public.assert_clean('display_name', new.display_name, 1::smallint); end if;
    if new.bio is distinct from old.bio then perform public.assert_clean('bio', new.bio, 1::smallint); end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_clean_text on public.debate_rooms;
create trigger trg_clean_text before insert or update on public.debate_rooms for each row execute function public.clean_text_guard();
drop trigger if exists trg_clean_text on public.communities;
create trigger trg_clean_text before insert or update on public.communities for each row execute function public.clean_text_guard();
drop trigger if exists trg_clean_text on public.community_posts;
create trigger trg_clean_text before insert or update on public.community_posts for each row execute function public.clean_text_guard();
drop trigger if exists trg_clean_text on public.community_comments;
create trigger trg_clean_text before insert or update on public.community_comments for each row execute function public.clean_text_guard();
drop trigger if exists trg_clean_text on public.clip_comments;
create trigger trg_clean_text before insert or update on public.clip_comments for each row execute function public.clean_text_guard();
drop trigger if exists trg_clean_text on public.room_messages;
create trigger trg_clean_text before insert or update on public.room_messages for each row execute function public.clean_text_guard();
/* Sign-up makes the users row with generated names; the welcome page's update_profile is the first gate. */
drop trigger if exists trg_clean_text on public.users;
create trigger trg_clean_text before update on public.users for each row execute function public.clean_text_guard();

